exercise.solution:
class LoginTracker:
    def __init__(self, max_failures=3):
        self._max_failures = max_failures
        self._failures = {}

    def record_failure(self, user):
        self._failures[user] = self._failures.get(user, 0) + 1

    def is_locked(self, user):
        return self._failures.get(user, 0) >= self._max_failures

    def reset(self, user):
        self._failures.pop(user, None)

    @property
    def locked_users(self):
        return sorted(user for user in self._failures if self.is_locked(user))

