exercise.solution:
class IPv4:
    def __init__(self, text):
        parts = text.split(".")
        valid = len(parts) == 4 and all(
            part.isascii() and part.isdigit() and 0 <= int(part) <= 255 for part in parts
        )
        if not valid:
            raise ValueError(f"invalid IPv4 address: {text!r}")
        self.octets = tuple(int(part) for part in parts)

    def __str__(self):
        return ".".join(str(octet) for octet in self.octets)

    def __repr__(self):
        return f"IPv4({str(self)!r})"

    def __eq__(self, other):
        return isinstance(other, IPv4) and self.octets == other.octets

    def __hash__(self):
        return hash(self.octets)

    @property
    def is_private(self):
        first, second = self.octets[:2]
        return first == 10 or (first == 172 and 16 <= second <= 31) or (first == 192 and second == 168)

