import hashlib
import hmac
import secrets

ROUNDS = 1_000


class AuthenticationError(Exception):
    """Raised when a password check fails."""


def hash_password(password, salt):
    digest = salt + password.encode()
    for _ in range(ROUNDS):
        digest = hashlib.sha256(digest).digest()
    return digest


class User:
    MIN_LENGTH = 8

    def __init__(self, name, password):
        self.name = name
        self.salt = secrets.token_bytes(16)
        self.password_hash = hash_password(password, self.salt)

    def check_password(self, candidate):
        candidate_hash = hash_password(candidate, self.salt)
        return hmac.compare_digest(candidate_hash, self.password_hash)

    def change_password(self, old, new):
        if not self.check_password(old):
            raise AuthenticationError("current password is incorrect")
        if len(new) < self.MIN_LENGTH:
            raise ValueError("new password must be at least 8 characters")
        self.salt = secrets.token_bytes(16)
        self.password_hash = hash_password(new, self.salt)

    def __repr__(self):
        return f"User(name={self.name!r})"

